<?php
/** @var array<string, mixed> $attributes */
declare( strict_types=1 );
if ( ! defined( 'ABSPATH' ) ) { exit; }
$items = nextsaas_items( $attributes, 'items' ); ?>
<section <?php echo nextsaas_section_attrs( 'home-our-team', $attributes, array( 'section', 'people' ) ); ?>><div class="container"><div class="section-heading"><p class="eyebrow" data-nextsaas-rich="eyebrow"><?php echo nextsaas_rich( nextsaas_attr( $attributes, 'eyebrow' ) ); ?></p><div class="heading-row"><h2 data-nextsaas-rich="heading"><?php echo nextsaas_rich( nextsaas_attr( $attributes, 'heading' ) ); ?></h2><p class="lead" data-nextsaas-rich="lead"><?php echo nextsaas_rich( nextsaas_attr( $attributes, 'lead' ) ); ?></p></div></div><div class="grid-3 people-grid"><?php foreach ( $items as $item ) : ?><article class="person-card"><?php if ( ! empty( $item['mediaUrl'] ) ) : ?><?php echo nextsaas_media( $item, 'portrait-reserve' ); ?><?php else : ?><div class="portrait-reserve" role="img" aria-label="<?php echo esc_attr( (string) ( $item['mediaAlt'] ?? '' ) ); ?>"><?php echo nextsaas_icon( 'user-round' ); ?><span><?php echo esc_html( (string) ( $item['placeholderLabel'] ?? '' ) ); ?></span></div><?php endif; ?><h3><?php echo esc_html( (string) ( $item['heading'] ?? '' ) ); ?></h3><p><?php echo esc_html( (string) ( $item['body'] ?? '' ) ); ?></p><div class="person-meta"><span><?php echo esc_html( (string) ( $item['meta'] ?? '' ) ); ?></span><?php echo nextsaas_icon( 'arrow-up-right' ); ?></div></article><?php endforeach; ?></div><p class="impact-note" data-nextsaas-rich="note"><?php echo nextsaas_rich( nextsaas_attr( $attributes, 'note' ) ); ?></p></div></section>
